        28.0 + (item - post) * 0.85
    } else if post < 12.0 {
        (12.0 - post) * 1.15
    } else {
        0.0
    };

    let fragmentation_penalty = fragmentation.powi(3) * 11.0;
    let remaining_space_bonus = remaining_ratio * 3.2;
    let mean_balance_penalty = ((mean - residual).abs() / capacity) * 6.5;
    let progress_pressure = progress * (1.0 - occupancy) * 4.0;

    let scarcity_penalty = if fitting_bins_count <= 1 {
        20.0 + (1.0 - progress) * 11.0
    } else {
        ((fitting_bins_count - 1) as f64).sqrt() * 0.7
    };

    let next_fit_bonus = if post >= next && next > 0.0 {
        let fit_quality = (next / post.max(1.0)).min(1.0);
        9.0 + fit_quality * 5.0 + (1.0 - progress) * 3.0
    } else if next > 0.0 {
        (next - post).min(capacity) * 0.14
    } else {
        0.0
    };

    let size_alignment_bonus = if post >= next && next > 0.0 {
        let closeness = 1.0 - (post - next).abs() / capacity.max(1.0);
        closeness * 4.0
    } else {
        0.0
    };

    let modulo_penalty = if bin_capacity >= 10 {
        let modulus = if bin_capacity % 10 == 0 { 10.0 } else { 5.0 };
        let waste = (post % modulus) / modulus;
        waste * (1.0 - occupancy) * 2.8
    } else {
        0.0
    };

    let pressure_bonus = if open_bins_count > 1 {
        (open_bins_count as f64).sqrt() * (1.0 - occupancy) * 0.45
    } else {
        0.0
    };

    let new_bin_penalty = if is_new_bin {
        34.0 + progress * 8.0 + (1.0 - progress) * 12.0
    } else {
        0.0
    };

    // Fine-grained residual utilization: reward bins whose residual space is
    // efficiently consumed, penalize slots that become stranded waste.
    let residual_efficiency = (item / residual.max(1.0)).min(1.0);
    let stranded_ratio = (post / capacity).min(1.0);
    let waste_severity = if post < item {
        1.0 + (item - post) / capacity
    } else {
        stranded_ratio * stranded_ratio
    };
    let residual_utilization_term = residual_efficiency * 8.5 - waste_severity * 5.2;

    // Lookahead coupling: preserve medium slots when the upcoming item is a
    // near-perfect fit, but prioritize large gaps for very large arrivals.
    let lookahead = if next > 0.0 {
        let near_fit = (1.0 - (post - next).abs() / capacity.max(1.0)).max(0.0);
        let upcoming_demand = (next / capacity).max(item_ratio);
        near_fit * upcoming_demand * 6.8
    } else {
        0.0
    };

    // Nonlinear opening threshold: a new bin is attractive only when existing
    // capacity is scarce or the current item is large relative to typical gaps.
    let opening_pressure = if is_new_bin {
        let demand_weight = (item_ratio * 1.35 + (1.0 - progress) * 0.55).min(1.8);
        let scarcity_weight = (fitting_bins_count <= 1) as u32 as f64;
        let pressure = demand_weight * 6.0 + scarcity_weight * 12.0;
        pressure + (post - item).abs() / capacity * 3.0
    } else {
        0.0
    };

    score += dead_space_penalty;
    score += fragmentation_penalty;
    score += mean_balance_penalty;
    score += progress_pressure;
    score += scarcity_penalty;
    score += modulo_penalty;
    score += pressure_bonus;
    score -= remaining_space_bonus;
    score -= next_fit_bonus;
    score -= size_alignment_bonus;
    score += new_bin_penalty;
    score -= residual_utilization_term;
    score -= lookahead;
    score += opening_pressure;

    score
}
